L["OPT_RESET_DEFAULTS"]        = "Reset to defaults"
L["OPT_RESET_DEFAULTS_DESC"]   = "Reset the settings alone, or everything Postbox keeps. Nothing changes until you choose."
L["MSG_RESET_CONFIRM"]         = "Reset Postbox to its defaults?\n\nReset settings: every option in this window goes back to how Postbox ships, its windows to their first size and place, and the arrangement to the default: the mail rows' columns, History's and Larger mail rows' own, the blocks under the list, and the category buttons' order and the ones you hid. Kept: your recipients (favorites, hidden, notes and names you added), your recent recipients, your character groups, your hidden characters, Mail Memory, History and how long it keeps mail, and whether the minimap icon is on.\n\nReset everything: all of that is cleared as well, and the minimap icon is switched off. Only the list of your characters is kept. You will be asked again first."
L["BTN_RESET"]                 = "Reset"
L["BTN_RESET_SETTINGS"]        = "Reset settings"
L["BTN_RESET_EVERYTHING"]      = "Reset everything"
L["MSG_RESET_ALL_CONFIRM"]     = "Reset everything?\n\nEvery setting goes back to its default and the minimap icon is switched off. Cleared: your recipients (favorites, hidden, notes and names you added), your recent recipients, your character groups, your hidden characters, Mail Memory and History.\n\nKept: the list of your characters. Postbox learns a character only when it logs in, and From alts, character groups and the Alts list on the Send tab depend on it.\n\nThis can't be undone."
L["MSG_RESET_ALL_DONE"]        = "Everything is reset. Postbox still knows your characters."
L["MSG_RESET_WAIT_COLLECT"]    = "Wait until Postbox has finished collecting or deleting mail, then reset."
L["MSG_RESET_WAIT_SEND"]       = "Wait until Postbox has finished sending, then reset."
