L["RM_EMPTY_FILTER_HINT"]      = "Pick another category above, or All to see every recipient."
L["RM_EMPTY_HIDDEN"]           = "Nothing is hidden.\n\nCheck Hide beside a name, or narrow the list to a category and use \"Hide all listed\", to keep characters out of the Send tab's recipient lists. Nothing is deleted, and this is where you get them back."
L["RM_EMPTY_FAVOURITES"]       = "No favorites yet.\n\nClick the star beside a name to make it a favorite. Favorites are offered first when you address a mail."
L["RM_ADD_TITLE"]              = "Add a recipient.\nName, or Name-Realm for another realm."
