L["RM_NOTE_ACCEPT"]            = "Save"
L["RM_DELETE_CONFIRM"]         = "Delete everything Postbox has stored for %s?\n\nIts hidden or favorite state, its note and its place in your recent recipients are removed. If the game offers the name again, it comes back."
L["RM_DELETE_CONFIRM_ALT"]     = "Delete everything Postbox has stored for %s?\n\nIts hidden or favorite state, its note and its place in your recent recipients are removed. %s is one of your characters: until you log in on it again, From alts counts its mail as another player's, and Character Groups and the Send tab's Alts list leave it out."
L["RM_DELETE_ACCEPT"]          = "Delete"
L["RM_DELETE_NOTHING"]         = "Postbox had nothing stored for %s."
