L["RM_BULK_HIDE_CONFIRM_ONE"]  = "Hide %d recipient?\n\nShowing: %s\n\nIt stays in this window: the Hidden category brings it back at any time. Favorites are never hidden by this."
L["RM_BULK_HIDE_CONFIRM_OTHER"] = "Hide %d recipients?\n\nShowing: %s\n\nThey stay in this window: the Hidden category brings them back at any time. Favorites are never hidden by this."
