  L["RM_LAST_YEARS_OTHER"]       = "il y a %d ans"
  L["RM_EMPTY"]                  = "Rien à gérer pour l'instant.\n\nCette fenêtre liste tous les personnages que Postbox peut proposer comme destinataires : tes alts, ta guilde, tes amis et tous ceux à qui tu as écrit. Masque ceux à qui tu n'écris jamais et ils cessent d'encombrer l'onglet Envoyer. Rien n'est supprimé, et tu peux les faire revenir ici à tout moment."
  L["RM_EMPTY_SEARCH"]           = "Aucun destinataire ne correspond à \"%s\"."
  L["RM_EMPTY_SEARCH_FILTER"]    = "Aucun destinataire correspondant à \"%s\" dans %s.\n\nLa recherche ne couvre que la catégorie sélectionnée : passe à Tous pour chercher parmi tous les destinataires."
  L["RM_EMPTY_FILTER"]           = "Rien dans %s.\n\nChoisis une autre catégorie ci-dessus, ou Tous pour voir tous les destinataires."
  L["RM_EMPTY_FILTER_HINT"]      = "Choisis une autre catégorie ci-dessus, ou Tous pour voir tous les destinataires."
  L["RM_EMPTY_HIDDEN"]           = "Rien n'est masqué.\n\nCoche Masquer à côté d'un nom, ou filtre la liste par catégorie puis utilise \"Masquer la liste\", pour garder des personnages hors des listes de destinataires de l'onglet Envoyer. Rien n'est supprimé, et c'est ici que tu les récupères."
  L["RM_EMPTY_FAVOURITES"]       = "Aucun favori pour l'instant.\n\nClique sur l'étoile à côté d'un nom pour en faire un favori. Les favoris sont proposés en premier lors de l'envoi d'un courrier."
