  L["RM_DELETE_CONFIRM"]         = "Supprimer tout ce que Postbox a enregistré pour %s ?\n\nSon état masqué ou favori, sa note et sa place dans tes destinataires récents sont effacés. Si le jeu propose de nouveau ce nom, il revient."
  L["RM_DELETE_CONFIRM_ALT"]     = "Supprimer tout ce que Postbox a enregistré pour %s ?\n\nSon état masqué ou favori, sa note et sa place dans tes destinataires récents sont effacés. %s est l'un de tes personnages : jusqu'à ta prochaine connexion avec lui, De mes rerolls compte son courrier comme celui d'un autre joueur, et les groupes de personnages et la liste Alts de l'onglet Envoyer ne le proposent plus."
  L["RM_DELETE_ACCEPT"]          = "Supprimer"
