  L["RM_BULK_HIDE_CONFIRM_ONE"]  = "Masquer %d destinataire ?\n\nAffichage : %s\n\nIl reste dans cette fenêtre : la catégorie Masqués le fait revenir à tout moment. Les favoris ne sont jamais masqués par cette action."
  L["RM_BULK_HIDE_CONFIRM_OTHER"] = "Masquer %d destinataires ?\n\nAffichage : %s\n\nIls restent dans cette fenêtre : la catégorie Masqués les fait revenir à tout moment. Les favoris ne sont jamais masqués par cette action."
  L["RM_BULK_SHOW_CONFIRM_ONE"]  = "Réafficher %d destinataire masqué ?\n\nAffichage : %s"
