  L["RM_OPT_BUTTON"]             = "Gérer les destinataires"
  L["RM_OPT_BUTTON_DESC"]        = "Choisis les personnages que Postbox propose lors de l'envoi d'un courrier.\n\nMasque les alts à qui tu n'écris jamais, et mets en favori ceux à qui tu écris."

  -- Options
  L["OPT_TAB_COUNTS_TITLE"]      = "Afficher le nombre de courriers"
  L["OPT_TAB_COUNTS_DESC"]       = "Des nombres sur Boîte et sur chaque bouton de collecte.\n\nBoîte compte tous les courriers de la boîte, lus compris ; un bouton compte ce qu'il récupérerait. Dans tous les cas, l'onglet Courrier porte un point tant qu'il reste du courrier à récupérer."
  L["OPT_READ_MAIL_TITLE"]       = "Courrier lu"
  L["OPT_READ_MAIL_DESC"]        = "Où va un courrier lu qui ne contient plus rien.\n\nSous la boîte : après le courrier à récupérer, sous un séparateur qui reste au bas d'une longue liste, avec Tout supprimer ; clique sur le séparateur pour les replier. Dans un onglet Terminé : un segment à part à côté de Boîte. Supprimer une fois traité : supprimé dès que Postbox en retire le dernier or ou objet, ou que tu cliques sur Retour après l'avoir lu ; l'historique garde son texte. Le courrier lu déjà présent reste sous le séparateur jusqu'à ce que tu le supprimes."
  L["OPT_READ_FOLD"]             = "Sous la boîte"
  L["OPT_READ_TAB"]              = "Dans un onglet Terminé"
  L["OPT_READ_DELETE"]           = "Supprimer une fois traité"
  L["OPT_HISTORY_KEEP_TITLE"]    = "Garder l'historique"
  L["OPT_HISTORY_KEEP_DESC"]     = "Combien de jours de courrier récupéré l'historique garde.\n\nPlus de jours donne un enregistrement plus lourd par personnage ; jamais plus de 1000 courriers. Jamais : l'historique est désactivé, son bouton quitte l'onglet Courrier, et ce qu'il gardait est effacé sur chaque personnage."
  L["OPT_HISTORY_DAYS_ONE"]      = "%d jour"
  L["OPT_HISTORY_DAYS_OTHER"]    = "%d jours"
  L["OPT_HISTORY_NEVER"]         = "Jamais"
  L["MSG_HISTORY_OFF_CONFIRM"]   = "Désactiver l'historique ?\n\nCe qu'il a gardé est effacé tout de suite sur chaque personnage. C'est irréversible."
  L["BTN_HISTORY_OFF"]           = "Désactiver"
  L["OPT_LARGER_ROWS_TITLE"]     = "Lignes de courrier plus grandes"
  L["OPT_LARGER_ROWS_DESC"]      = "Deux lignes par courrier, avec une icône plus grande et tous ses chiffres sous son nom.\n\nDésactivé, chaque courrier tient sur une ligne et la liste en montre davantage."
  L["OPT_ROW_LAYOUT_TITLE"]      = "Disposition des lignes"
  L["OPT_ROW_LAYOUT_DESC"]       = "Comment s'alignent les chiffres sur les lignes de courrier simples.\n\nL'historique, la Mémoire du courrier et la boîte d'un autre personnage utilisent toujours une seule ligne, et l'onglet Courrier aussi tant que les lignes de courrier plus grandes sont désactivées. Colonnes : chaque chiffre reste sous son en-tête, et un long sujet continue dans les colonnes que son courrier laisse vides. Compacte : les chiffres de chaque ligne se resserrent, loin du sujet, et le sujet prend la place."
  L["OPT_ROW_LAYOUT_LARGER"]     = "Les lignes de courrier plus grandes sont activées : les lignes de l'onglet Courrier tiennent sur deux lignes et resserrent toujours les chiffres de leur deuxième ligne. L'historique, la Mémoire du courrier et la boîte d'un autre personnage restent sur une ligne et suivent toujours ce réglage."
  L["OPT_ROW_LAYOUT_COLUMNS"]    = "Colonnes"
  L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Chaque chiffre reste sous son en-tête."
  L["OPT_ROW_LAYOUT_PACKED"]     = "Compacte"
  L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Les chiffres de chaque ligne se resserrent ; le sujet prend la place."
  L["ARRANGE_NOTE_PACKED"]       = "Compacte : un courrier qui ne l'a pas ne laisse pas de vide, et le sujet prend sa place."
  L["ARRANGE_LAYOUT_WHERE"]      = "Disposition des lignes en décide, dans la vue d'ensemble ou dans les options, onglet Courrier."
  L["ARRANGE_LANES_ON"]          = "Chaque chiffre garde sa colonne sur chaque ligne. Un long sujet continue dans les colonnes que son courrier laisse vides, jusqu'au premier chiffre du courrier."
  L["OPT_QUALITY_OFF"]           = "Désactivé"
  L["OPT_KEEP_FREE_TITLE"]       = "Garder des places libres"
  L["OPT_KEEP_FREE_DESC"]        = "La récupération s'arrête en laissant ce nombre d'emplacements libres.\n\nDe la place pour le butin et l'artisanat. Une récupération s'arrête avant l'objet qui en occuperait un, et le dit ; l'or est quand même pris. Un courrier ou un objet sur lequel tu cliques toi-même est pris quand même. Seuls les sacs ordinaires comptent, pas le sac de composants. Aucun : la récupération continue jusqu'à ce que tes sacs soient pleins."
  L["OPT_KEEP_FREE_NONE"]        = "Aucun"
  L["STATUS_KEPT_FREE_ONE"]      = "Arrêté pour garder %d emplacement libre"
  L["STATUS_KEPT_FREE_OTHER"]    = "Arrêté pour garder %d emplacements libres"
  L["MSG_COLLECT_STOPPED_KEEP_ONE"] = "%d courrier est toujours dans la boîte aux lettres : la récupération s'est arrêtée pour ne pas occuper %s."
  L["MSG_COLLECT_STOPPED_KEEP_OTHER"] = "%d courriers sont toujours dans la boîte aux lettres : la récupération s'est arrêtée pour ne pas occuper %s."
  L["ROOM_KEPT_ONE"]             = "La récupération garde %d emplacement libre"
  L["ROOM_KEPT_OTHER"]           = "La récupération garde %d emplacements libres"
  L["BAGS_KEPT_EXTRA"]           = " (+%d gardés libres)"
  L["OPT_ATTACH_HOVER_TITLE"]    = "Pièces jointes au survol"
  L["OPT_ATTACH_HOVER_DESC"]     = "Ce qu'affiche le pointeur posé sur l'icône d'un courrier qui contient plusieurs objets.\n\nInfobulle : la liste de tout ce qu'il contient. Éventail : après un instant, les objets s'étalent à côté de l'icône, l'or en premier. Clic pour en prendre un, Maj-clic pour le lier, Ctrl-clic pour l'essayer. Un courrier C.R. demande toujours avant que rien ne soit pris."
  L["OPT_ATTACH_HOVER_TOOLTIP"]  = "Infobulle"
  L["OPT_ATTACH_HOVER_FAN"]      = "Éventail"
  L["FAN_TILE_HINT"]             = "Clic pour prendre · Maj-clic pour lier"
  L["FAN_GOLD_HINT"]             = "Clic pour prendre"
  L["FAN_TILE_BAGS"]             = "Tes sacs sont pleins : fais de la place pour le prendre."
  L["OPT_ICON_COUNTS_TITLE"]     = "Quantités sur les icônes"
  L["OPT_ICON_COUNTS_DESC"]      = "La taille de la pile sur le coin de l'icône d'un objet, comme dans les sacs, et le bord d'une seconde carte derrière l'icône quand le courrier contient plus d'un objet. Le nom d'un courrier de l'hôtel des ventes omet alors la quantité que son icône montre déjà.\n\nL'onglet Courrier, l'historique et la mémoire du courrier la suivent tous."
  L["HINT_ICON_TAKE_RIGHT"]      = "Clic droit pour ouvrir et prendre un par un"
  L["HINT_ICON_TAKE_CLICK"]      = "Clic pour ouvrir et prendre un par un"
  L["OPT_QUALITY_ICON_TITLE"]    = "Qualité sur les icônes"
  L["OPT_QUALITY_ICON_DESC"]     = "La marque de qualité d'artisanat sur le coin de l'icône d'un objet dans les listes de courrier.\n\nL'onglet Courrier, l'historique et la mémoire du courrier la suivent tous."
  L["OPT_QUALITY_NAME_TITLE"]    = "Qualité près du nom"
  L["OPT_QUALITY_NAME_DESC"]     = "Une marque de qualité d'artisanat à côté du nom d'un objet dans les listes de courrier, seule ou avec celle de l'icône.\n\nAvant le nom, les noms restent alignés. Après, comme dans un lien du chat, la marque s'affiche toujours en entier : un nom long est raccourci pour lui faire place. L'onglet Courrier, l'historique et la mémoire du courrier la suivent tous."
  L["OPT_QUALITY_NAME_BEFORE"]   = "Avant"
  L["OPT_QUALITY_NAME_AFTER"]    = "Après"
  L["HISTORY_AGE_M"]             = "%d min"
  L["HISTORY_AGE_H"]             = "%d h"
  L["HISTORY_AGE_D"]             = "%d j"
  L["HISTORY_DATE_DM"]           = "{d} {m}"
  L["HISTORY_DATE_MD"]           = "{m} {d}"
  L["HISTORY_DATE_DM_YEAR"]      = "{d} {m} {y}"
  L["HISTORY_DATE_MD_YEAR"]      = "{m} {d} {y}"
  L["OPT_SLOTS_WORDS"]           = "Nombre et mot"
  L["OPT_SLOTS_NUMBER"]          = "Nombre seul"
  L["COL_READ_STUCK"]            = "Un courrier bloqué, qui n'a pas pu être récupéré, affiche ici un triangle d'avertissement."
  L["OPT_PREVIEW_CLICK_TITLE"]   = "Le clic gauche ouvre le courrier"
  L["OPT_PREVIEW_CLICK_DESC"]    = "Le clic gauche ouvre le courrier et le clic droit le récupère.\n\nDésactivé, les deux s'échangent : le clic gauche récupère et le clic droit ouvre sans récupérer."
  L["OPT_ATTACH_MAIL_TITLE"]     = "Joindre depuis Courrier"
  L["OPT_ATTACH_MAIL_DESC"]      = "Un clic droit sur un objet du sac dans l'onglet Courrier passe à Envoyer et le joint.\n\nDésactivé, les objets s'y comportent normalement. L'onglet Envoyer joint dans les deux cas."
  L["OPT_AFTER_SEND_TITLE"]      = "Après l'envoi, garder"
  L["OPT_AFTER_SEND_DESC"]       = "Ce qui reste dans le formulaire une fois le courrier parti.\n\nRien : tout s'efface et le courrier suivant part de zéro. Destinataire : le nom reste, le suivant pour le même personnage n'a pas à être retapé. Destinataire et sujet : les deux restent, pour une série de courriers au même personnage. Le message, les pièces jointes et l'or s'effacent toujours."
  L["OPT_AFTER_SEND_NOTHING"]    = "Rien"
  L["OPT_AFTER_SEND_RECIPIENT"]  = "Destinataire"
  L["OPT_AFTER_SEND_SUBJECT"]    = "Destinataire et sujet"
  L["OPT_CATEGORY_BUTTONS_TITLE"] = "Boutons de catégorie"
  L["OPT_CATEGORY_BUTTONS_DESC"] = "Des boutons de collecte en un clic sous la liste, un par type de courrier.\n\nAcheté, vendu, annulé, expiré, autre, de mes rerolls, et un par groupe de personnages. Désactivé, seul Tous les courriers reste et la liste gagne la place. Les masquer ou les afficher en organisant revient à ce même réglage ; on peut aussi y déplacer ou masquer chaque bouton."
  L["OPT_ROWS_HEADING"]          = "Lignes de courrier"
  L["OPT_GOLD_BOTH"]             = "Gagné et dépensé"
  L["OPT_GOLD_EARNED"]           = "Gagné seulement"
  L["OPT_GOLD_SPENT"]            = "Dépensé seulement"
  L["OPT_EXPIRY_ALWAYS"]         = "Toujours"
  L["OPT_EXPIRY_UNDER_ONE"]      = "Sous %d jour"
  L["OPT_EXPIRY_UNDER_OTHER"]    = "Sous %d jours"
  L["COMPARTMENT_TIP"]           = "Clic pour la mémoire du courrier, la boîte de chaque personnage · Clic droit pour les options"
  L["OPT_ROW_GOLD"]              = "Or"
  L["OPT_ROW_GOLD_DESC"]         = "L'or qu'apporte un courrier, en vert, et le coût d'un achat aux enchères, en rouge : choisis lesquels, pour ces lignes seulement. Un prix C.R. s'affiche toujours, car Postbox n'en paie jamais un sans demander."
  L["OPT_ROW_SLOTS"]             = "Emplacements"
  L["OPT_ROW_SLOTS_DESC"]        = "Combien d'emplacements de pièce jointe un courrier occupe encore. Masquée, le nombre passe dans l'infobulle de la ligne."
  L["OPT_ROW_EXPIRY"]            = "Temps restant"
  L["OPT_ROW_EXPIRY_DESC"]       = "Le temps qu'il reste à un courrier, en ambre sous trois jours (un pour un C.R.). Choisis quand ces lignes l'affichent ; il est toujours dans l'infobulle."
  L["ARRANGE_TITLE"]             = "Organiser"
  L["ARRANGE_TIP"]               = "Déplace et masque les colonnes d'une ligne de courrier et les blocs sous la liste, et choisis ce qu'affichent Or, Temps restant, Emplacements et Récupéré.\n\nChaque disposition garde ses propres colonnes et choix : l'onglet Courrier et la Mémoire du courrier en partagent une, et l'historique et les lignes de courrier plus grandes ont chacun la leur."
  L["ARRANGE_DONE"]              = "Terminé"
  L["FRAME_TITLE_PREVIEW"]       = "Postbox · Aperçu"
  L["ARRANGE_PREVIEW_AWAY"]      = "Aucune boîte aux lettres n'est ouverte. Ceci est du courrier d'exemple."
  L["PREVIEW_SEND_OFF"]          = "Ouvre une boîte aux lettres pour envoyer."
