  L["OPT_RESET_DEFAULTS"]        = "Réinitialiser les options"
  L["OPT_RESET_DEFAULTS_DESC"]   = "Réinitialise les réglages seuls, ou tout ce que Postbox conserve. Rien ne change avant ton choix."
  L["MSG_RESET_CONFIRM"]         = "Remettre Postbox par défaut ?\n\nRéinitialiser les réglages : chaque option de cette fenêtre revient à son état d'origine, les fenêtres de Postbox à leur taille et leur place de départ, et la disposition à celle par défaut : les colonnes des lignes de courrier, celles de l'Historique et des lignes de courrier plus grandes, les blocs sous la liste, ainsi que l'ordre des boutons de catégorie et ceux que tu as masqués. Conservés : tes destinataires (favoris, masqués, notes et noms ajoutés par toi), tes destinataires récents, tes groupes de personnages, tes personnages masqués, la Mémoire du courrier, l'Historique et sa durée de conservation, ainsi que l'icône de la minicarte, activée ou non.\n\nTout réinitialiser : tout cela est effacé aussi, et l'icône de la minicarte est désactivée. Seule la liste de tes personnages est conservée. Une confirmation te sera d'abord demandée."
  L["BTN_RESET"]                 = "Réinitialiser"
  L["BTN_RESET_SETTINGS"]        = "Réinitialiser les réglages"
  L["BTN_RESET_EVERYTHING"]      = "Tout réinitialiser"
  L["MSG_RESET_ALL_CONFIRM"]     = "Tout réinitialiser ?\n\nChaque réglage revient à sa valeur par défaut et l'icône de la minicarte est désactivée. Effacés : tes destinataires (favoris, masqués, notes et noms ajoutés par toi), tes destinataires récents, tes groupes de personnages, tes personnages masqués, la Mémoire du courrier et l'Historique.\n\nConservée : la liste de tes personnages. Postbox ne découvre un personnage que lorsqu'il se connecte, et De mes rerolls, les groupes de personnages et la liste Alts de l'onglet Envoyer en dépendent.\n\nCette action est irréversible."
  L["MSG_RESET_ALL_DONE"]        = "Tout est réinitialisé. Postbox connaît toujours tes personnages."
  L["MSG_RESET_WAIT_COLLECT"]    = "Attends que Postbox ait fini de récupérer ou de supprimer le courrier, puis réinitialise."
  L["MSG_RESET_WAIT_SEND"]       = "Attends que Postbox ait fini d'envoyer, puis réinitialise."
  L["OPT_MINIMAP_SIZE_TITLE"]    = "Taille de l'icône"
