  L["STATUS_REMAINING"]          = "Verbleibend: %d"
  L["STATUS_DONE"]               = "Fertig"
  L["STATUS_COLLECTED"]          = "Abgeholt: %d"
  L["STATUS_STOPPED"]            = "Abgebrochen: der Briefkasten ging zu"
  L["STATUS_INCOMPLETE"]         = "Unvollständig: %d übrig"
  L["STATUS_PARTIAL"]            = "Steckt fest: %d"
  L["STATUS_STUCK"]              = "Steckt fest: %d"
  L["GRIP_TIP_DRAG"]             = "Ziehen zum Ändern der Größe"
  L["GRIP_TIP_RESET"]            = "Rechtsklick zum Zurücksetzen"

  -- Kategorienamen: Sammelknopf UND Etikett auf einer einzelnen Postzeile.
  L["CAT_ALL"]                   = "Alle Post"
  L["CAT_EXPIRED"]               = "Alle abgelaufen"
  L["CAT_SOLD"]                  = "Alle verkauft"
  L["CAT_CANCELED"]              = "Alle abgebrochen"
  L["CAT_BOUGHT"]                = "Alle gekauft"
  L["CAT_OTHER"]                 = "Sonstige"
  L["CAT_ALTS"]                  = "Von Twinks"
  L["CAT_ALTS_TIP"]              = "Post von deinen eigenen Charakteren: jeder, mit dem du dich bei installiertem Postbox eingeloggt hast, auf jedem Realm."
  L["CAT_OTHER_TIP"]             = "Post, die nicht vom Auktionshaus und nicht von deinen eigenen Charakteren kommt: Briefe anderer Spieler und Post des Spiels."

