  -- Optionen
  L["OPT_TAB_COUNTS_TITLE"]      = "Anzahl der Briefe anzeigen"
  L["OPT_TAB_COUNTS_DESC"]       = "Zahlen am Posteingang und an jedem Abhol-Button.\n\nPosteingang zählt jeden Brief im Postfach, gelesene eingeschlossen; ein Button zählt, was er abholen würde. In jedem Fall trägt der Post-Tab einen Punkt, solange Post abzuholen ist."
  L["OPT_READ_MAIL_TITLE"]       = "Gelesene Post"
  L["OPT_READ_MAIL_DESC"]        = "Wohin gelesene Post ohne Inhalt kommt.\n\nUnter dem Posteingang: nach der abzuholenden Post, unter einem Trenner, der am Fuß einer langen Liste stehen bleibt, mit Alle löschen; ein Klick auf den Trenner klappt sie ein. Im Tab Erledigt: ein eigenes Segment neben Posteingang. Löschen, wenn erledigt: gelöscht, sobald Postbox das letzte Gold oder den letzten Gegenstand herausnimmt oder du nach dem Lesen auf Zurück klickst; der Verlauf behält ihren Text. Bereits gelesene Post bleibt unter dem Trenner, bis du sie löschst."
  L["OPT_READ_FOLD"]             = "Unter dem Posteingang"
  L["OPT_READ_TAB"]              = "Im Tab Erledigt"
  L["OPT_READ_DELETE"]           = "Löschen, wenn erledigt"
  L["OPT_HISTORY_KEEP_TITLE"]    = "Verlauf behalten"
  L["OPT_HISTORY_KEEP_DESC"]     = "Wie viele Tage abgeholter Post der Verlauf zeigt.\n\nMehr Tage heißt mehr gespeicherte Daten pro Charakter; nie mehr als 1000 Briefe. Nie: Der Verlauf ist aus, seine Schaltfläche verschwindet aus dem Post-Tab, und was er behalten hat, wird bei jedem Charakter gelöscht."
  L["OPT_HISTORY_DAYS_ONE"]      = "%d Tag"
  L["OPT_HISTORY_DAYS_OTHER"]    = "%d Tage"
  L["OPT_HISTORY_NEVER"]         = "Nie"
  L["MSG_HISTORY_OFF_CONFIRM"]   = "Verlauf ausschalten?\n\nWas er gespeichert hat, wird sofort auf jedem Charakter gelöscht. Das lässt sich nicht rückgängig machen."
  L["BTN_HISTORY_OFF"]           = "Ausschalten"
  L["OPT_LARGER_ROWS_TITLE"]     = "Größere Postzeilen"
  L["OPT_LARGER_ROWS_DESC"]      = "Zwei Zeilen je Brief, mit größerem Symbol und allen Angaben unter dem Namen.\n\nAus, bekommt jeder Brief eine Zeile und die Liste zeigt mehr."
  L["OPT_ROW_LAYOUT_TITLE"]      = "Zeilenlayout"
  L["OPT_ROW_LAYOUT_DESC"]       = "Wie die Angaben in einzeiligen Postzeilen stehen.\n\nVerlauf, Postgedächtnis und der Briefkasten eines anderen Charakters sind immer einzeilig, der Post-Tab ebenfalls, solange größere Postzeilen aus sind. Spalten: Jede Angabe bleibt unter ihrer Überschrift, und ein langer Betreff läuft in die Spalten weiter, die sein Brief leer lässt. Kompakt: Die Angaben jeder Zeile rücken zusammen, weg vom Betreff, und der Betreff bekommt den Platz."
  L["OPT_ROW_LAYOUT_LARGER"]     = "Größere Postzeilen sind an: Die Zeilen im Post-Tab sind zweizeilig und rücken die Angaben ihrer zweiten Zeile immer zusammen. Verlauf, Postgedächtnis und der Briefkasten eines anderen Charakters bleiben einzeilig und folgen weiter dieser Wahl."
  L["OPT_ROW_LAYOUT_COLUMNS"]    = "Spalten"
  L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Jede Angabe bleibt unter ihrer Überschrift."
  L["OPT_ROW_LAYOUT_PACKED"]     = "Kompakt"
  L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Die Angaben jeder Zeile rücken zusammen; der Betreff bekommt den Platz."
  L["ARRANGE_NOTE_PACKED"]       = "Kompakt: Ein Brief ohne sie lässt keine Lücke, und der Betreff bekommt ihren Platz."
  L["ARRANGE_LAYOUT_WHERE"]      = "Das entscheidet Zeilenlayout, in der Übersicht oder in den Optionen, Post-Tab."
  L["ARRANGE_LANES_ON"]          = "Jede Angabe behält ihre Spalte in jeder Zeile. Ein langer Betreff läuft in die Spalten weiter, die sein Brief leer lässt, bis zur ersten Angabe des Briefs."
  L["OPT_QUALITY_OFF"]           = "Aus"
  L["OPT_KEEP_FREE_TITLE"]       = "Taschenplätze freihalten"
  L["OPT_KEEP_FREE_DESC"]        = "Das Abholen stoppt, solange noch so viele Taschenplätze frei sind.\n\nPlatz für Beute und Handwerk. Ein Abholen stoppt vor dem Gegenstand, der einen davon belegen würde, und sagt es; Gold wird trotzdem genommen. Eine Post oder ein Gegenstand, den du selbst anklickst, wird trotzdem genommen. Es zählen nur die normalen Taschen, nicht die Reagenzientasche. Keine: Das Abholen geht weiter, bis die Taschen voll sind."
  L["OPT_KEEP_FREE_NONE"]        = "Keine"
  L["STATUS_KEPT_FREE_ONE"]      = "Gestoppt, um %d Taschenplatz freizuhalten"
  L["STATUS_KEPT_FREE_OTHER"]    = "Gestoppt, um %d Taschenplätze freizuhalten"
  L["MSG_COLLECT_STOPPED_KEEP_ONE"] = "%d Brief ist noch im Briefkasten: Das Abholen wurde gestoppt, um %s freizuhalten."
  L["MSG_COLLECT_STOPPED_KEEP_OTHER"] = "%d Briefe sind noch im Briefkasten: Das Abholen wurde gestoppt, um %s freizuhalten."
  L["ROOM_KEPT_ONE"]             = "Abholen hält %d Taschenplatz frei"
  L["ROOM_KEPT_OTHER"]           = "Abholen hält %d Taschenplätze frei"
  L["BAGS_KEPT_EXTRA"]           = " (+%d freigehalten)"
  L["OPT_ATTACH_HOVER_TITLE"]    = "Anhänge beim Darüberfahren"
  L["OPT_ATTACH_HOVER_DESC"]     = "Was der Mauszeiger auf dem Symbol eines Briefs mit mehreren Gegenständen zeigt.\n\nTooltip: eine Liste von allem, was darin ist. Auffächern: nach einem Moment breiten sich die Gegenstände neben dem Symbol aus, das Gold zuerst. Klick nimmt einen, Umschalt-Klick verlinkt ihn, Strg-Klick probiert ihn an. Ein NN-Brief fragt weiterhin, bevor etwas genommen wird."
  L["OPT_ATTACH_HOVER_TOOLTIP"]  = "Tooltip"
  L["OPT_ATTACH_HOVER_FAN"]      = "Auffächern"
  L["FAN_TILE_HINT"]             = "Klick zum Nehmen · Umschalt-Klick zum Verlinken"
  L["FAN_GOLD_HINT"]             = "Klick zum Nehmen"
  L["FAN_TILE_BAGS"]             = "Deine Taschen sind voll: schaffe Platz, um es zu nehmen."
  L["OPT_ICON_COUNTS_TITLE"]     = "Stapelgröße auf Symbolen"
  L["OPT_ICON_COUNTS_DESC"]      = "Die Stapelgröße in der Ecke des Gegenstandssymbols, wie in den Taschen, und die Kante einer zweiten Karte hinter dem Symbol, wenn der Brief mehr als einen Gegenstand enthält. Der Name eines Auktionshausbriefs lässt dann die Anzahl weg, die sein Symbol schon zeigt.\n\nPost-Tab, Verlauf und Postgedächtnis folgen der Wahl."
  L["HINT_ICON_TAKE_RIGHT"]      = "Rechtsklick zum Öffnen und einzeln Nehmen"
