  L["OPT_QUALITY_NAME_TITLE"]    = "Qualität am Namen"
  L["OPT_QUALITY_NAME_DESC"]     = "Ein Handwerksqualitätssymbol neben dem Namen eines Gegenstands in den Postlisten, allein oder mit dem auf dem Symbol.\n\nDavor bleiben die Namen bündig. Dahinter, wie im Chatlink, ist das Symbol immer ganz zu sehen: ein langer Name wird dafür gekürzt. Post-Tab, Verlauf und Postgedächtnis folgen der Wahl."
