  L["PERF_REC_TITLE"]            = "Leistungsaufzeichnung"
  L["PERF_REC_DESC"]             = "Zeichnet auf, wie lange jeder Besuch am Briefkasten dauert, für die Meldung eines langsamen Briefkastens. Standardmäßig aus."
  L["PERF_REC_OFF"]              = "Aus"
  L["PERF_REC_ON"]               = "An"
  L["PERF_REC_DETAIL"]           = "Ausführlich"
  L["PERF_REC_OFF_DESC"]         = "Nichts wird gemessen. Der Bericht enthält weiterhin die Werte des spieleigenen Profilers."
  L["PERF_REC_ON_DESC"]          = "Misst jeden Besuch am Briefkasten ab dem nächsten: das Öffnen, das Füllen des Posteingangs, Tabwechsel und das Schließen. Bleibt nach einem /reload an, bis du es ausschaltest."
  L["PERF_REC_DETAIL_DESC"]      = "Wie An, dazu, was der Posteingang bei jedem Besuch enthielt und welche Gegenstandsdaten das Spiel dabei geladen hat. Etwas mehr Arbeit bei jedem Besuch."
  L["PERF_REC_CHAT"]             = "Leistungsaufzeichnung: %s."
  L["OPT_BUG_HINT"]              = "Strg+C kopiert den markierten Text."
  L["OPT_RESET_DEFAULTS"]        = "Auf Standard zurücksetzen"
  L["OPT_RESET_DEFAULTS_DESC"]   = "Setzt nur die Einstellungen zurück oder alles, was Postbox speichert. Nichts ändert sich, bevor du wählst."
  L["MSG_RESET_CONFIRM"]         = "Postbox auf Standard zurücksetzen?\n\nEinstellungen zurücksetzen: Jede Option in diesem Fenster kehrt zum Auslieferungszustand zurück, die Fenster von Postbox zu ihrer ersten Größe und Position und die Anordnung zum Standard: die Spalten der Postzeilen, die eigenen des Verlaufs und der größeren Postzeilen, die Blöcke unter der Liste sowie die Reihenfolge der Kategorie-Buttons und die, die du ausgeblendet hast. Erhalten bleiben: deine Empfänger (Favoriten, ausgeblendete, Notizen und von dir hinzugefügte Namen), deine letzten Empfänger, deine Charaktergruppen, deine ausgeblendeten Charaktere, das Postgedächtnis, der Verlauf und wie lange er aufbewahrt wird, sowie ob das Minikarten-Symbol an ist.\n\nAlles zurücksetzen: All das wird ebenfalls gelöscht, und das Minikarten-Symbol wird ausgeschaltet. Nur die Liste deiner Charaktere bleibt erhalten. Du wirst vorher noch einmal gefragt."
  L["BTN_RESET"]                 = "Zurücksetzen"
  L["BTN_RESET_SETTINGS"]        = "Einstellungen zurücksetzen"
  L["BTN_RESET_EVERYTHING"]      = "Alles zurücksetzen"
  L["MSG_RESET_ALL_CONFIRM"]     = "Alles zurücksetzen?\n\nJede Einstellung kehrt zu ihrem Standard zurück, und das Minikarten-Symbol wird ausgeschaltet. Gelöscht werden: deine Empfänger (Favoriten, ausgeblendete, Notizen und von dir hinzugefügte Namen), deine letzten Empfänger, deine Charaktergruppen, deine ausgeblendeten Charaktere, das Postgedächtnis und der Verlauf.\n\nErhalten bleibt: die Liste deiner Charaktere. Postbox lernt einen Charakter erst kennen, wenn er sich einloggt, und Von Twinks, die Charaktergruppen und die Liste Alts im Senden-Tab hängen davon ab.\n\nDas lässt sich nicht rückgängig machen."
  L["MSG_RESET_ALL_DONE"]        = "Alles ist zurückgesetzt. Postbox kennt deine Charaktere weiterhin."
  L["MSG_RESET_WAIT_COLLECT"]    = "Warte, bis Postbox mit dem Abholen oder Löschen der Post fertig ist, und setze dann zurück."
  L["MSG_RESET_WAIT_SEND"]       = "Warte, bis Postbox mit dem Senden fertig ist, und setze dann zurück."
