  L["MINIMAP_TIP_UNLOCK"]        = "Alt-Klick zum Entsperren"
  L["OPT_MINIMAP_LOCK_TITLE"]    = "Position sperren"
  L["OPT_MINIMAP_LOCK_DESC"]     = "Verhindert, dass Umschalt-Ziehen das Symbol verschiebt - kein versehentliches Verrutschen.\n\nEin Alt-Klick auf das Symbol sperrt und entsperrt es ebenfalls."
  L["OPT_MEMORY_TITLE"]          = "Postgedächtnis"
  L["OPT_MEMORY_DESC"]           = "Merkt sich, was im Briefkasten jedes Charakters beim letzten Besuch lag.\n\nFern vom Briefkasten zeigt es das Minikartensymbol, das Addon-Fach oder /postbox mail; am Briefkasten die Schaltfläche Charaktere neben der Suche im Post-Tab. Aus, wird nichts aufgezeichnet."
  L["OPT_MEMORY_SWITCH"]         = "Briefkästen merken"
  L["PICKER_HIDE_HINT"]          = "Rechtsklick zum Ausblenden dieses Charakters"
  L["PICKER_HIDDEN"]             = "Ausgeblendet (%d)"
  L["PICKER_SHOW"]               = "Einblenden"
  L["PICKER_SHOW_TIP"]           = "Klick nimmt ihn wieder in Charakterliste, Suche und Warnungen auf"
  L["HIDDEN_TITLE"]              = "Ausgeblendete Charaktere"
  L["HIDDEN_DESC"]               = "Fehlen in der Charakterliste, in der Suche über alle Charaktere und in den Warnungen.\n\nPostbox merkt sich ihre Post weiter: Blendest du einen wieder ein, ist alles wieder da. Rechtsklick auf einen Namen in der Charakterliste blendet ihn aus."
  L["OPT_HIDDEN_NONE"]           = "Keine"
  L["OPT_HIDDEN_SHOW_ALL"]       = "Alle einblenden"
  L["OPT_HIDDEN_SHOW_ALL_DESC"]  = "Nimmt jeden ausgeblendeten Charakter wieder in die Charakterliste, die Suche und die Warnungen auf."
  L["MEMORY_NO_OTHERS_HIDDEN"]   = "Keiner deiner anderen Charaktere hat Post, die sich zeigen lässt, außer denen, die du ausgeblendet hast. Blende sie in den Postbox-Optionen unter Postgedächtnis wieder ein."
  L["PICKER_BACK_HINT"]          = "Rechtsklick zurück zu deinem Briefkasten"
