  L["MEMORY_NO_OTHERS"]          = "Keiner deiner anderen Charaktere hat Post, die sich zeigen lässt."
  L["OPT_MINIMAP_ACCENT_TITLE"]  = "Akzent"
  L["OPT_MINIMAP_ACCENT_DESC"]   = "Färbt das Leuchten und jeden Symbolstil, der Einfärben unterstützt, in Postbox' Akzentfarbe.\n\nDieselbe wie in den Fenstern: der Akzent deines Host-UIs bei aktivem Skin, sonst Postbox' eigenes Gold."
  L["OPT_MINIMAP_GLOW_TITLE"]    = "Leuchten"
