  L["OPT_SCALE_TITLE"]           = "Fenstergröße"
  L["OPT_SCALE_DESC"]            = "Wie groß die Fenster von Postbox sind, in jedem Stil.\n\nTexte und Bedienelemente wachsen mit dem Fenster, und jedes Fenster bleibt, wo es ist."
  L["OPT_GROUP_COLORS"]          = "Farben"
