  L["OPT_BORDER_DESC_POSTBOX"]   = "Die Linie um die Fenster von Postbox: außen schwarz, innen grau.\n\nDick verdoppelt die graue Linie; Keiner lässt den Rand frei."
  L["OPT_FONT_TITLE"]            = "Schriftart"
  L["OPT_FONT_DESC"]             = "Die Schrift der Texte von Postbox.\n\nSpielschrift ist die, die dein Spiel überall verwendet. Eine Schrift ohne die Buchstaben deiner Sprache wird nicht angeboten."
