  L["OPT_MODE_TITLE"]            = "Modus"
  L["OPT_MODE_DESC"]             = "Dunkel: fast schwarzes Glas, der Look, in dem Postbox entworfen wurde. Hell: ein papierhelles Fenster mit dunkler Schrift, jede Farbe darauf lesbar gemacht.\n\nIm hellen Modus bleibt das Fenster fast deckend: eine Deckkraft unter 85 wird bei 85 gehalten."
  L["OPT_MODE_DARK"]             = "Dunkel"
  L["OPT_MODE_LIGHT"]            = "Hell"
  L["OPT_ACCENT_TITLE"]          = "Akzentfarbe"
  L["OPT_ACCENT_DESC"]           = "Die eine Farbe, die etwas bedeutet: der offene Tab, Überschriften, Häkchen und das Gewählte.\n\nEine Farbe, die zu dunkel zum Lesen ist (oder im hellen Modus zu blass), wird dort, wo sie gemalt wird, aufgehellt oder abgedunkelt und behält ihren Farbton; die gewählte Farbe bleibt gespeichert."
  L["OPT_ACCENT_GOLD"]           = "Postbox-Gold"
