  L["OPT_SURFACE_TITLE"]         = "Fläche"
  L["OPT_SURFACE_DESC"]          = "Die Farbe des Fensters hinter allem, im dunklen Modus.\n\nSie bleibt dunkel und fast neutral, was auch immer du wählst, damit Text seinen Kontrast behält. Der helle Modus hat seine eigene Papierfarbe."
  L["OPT_SURFACE_CHARCOAL"]      = "Anthrazit"
