  L["OPT_SURFACE_SLATE"]         = "Schiefer"
  L["OPT_SURFACE_UMBER"]         = "Umbra"
  L["OPT_BG_OPACITY_DESC_POSTBOX"] = "Wie viel von der Welt durch den Hintergrund der Postbox-Fenster scheint.\n\nTexte und Bedienelemente bleiben bei jeder Einstellung deckend, und dieses Optionsfenster bleibt immer deckend. Im hellen Modus wird eine Deckkraft unter 85 bei 85 gehalten."
  L["OPT_TINT_TITLE"]              = "Tönung"
  L["OPT_TINT_DESC"]               = "Ein leiser Farbton in der Fensterfarbe und der Titelleiste: keiner, der deines Akzents oder deiner Klassenfarbe. Text wird nie getönt."
  L["OPT_TINT_NONE"]               = "Keine"
  L["OPT_BORDER_COLOR_TITLE"]      = "Rahmenfarbe"
  L["OPT_BORDER_COLOR_DESC"]       = "Die innere Linie des Fensterrahmens: ein Grau, dein Akzent oder eine eigene Farbe. Die äußere Linie bleibt dunkel."
