  -- Opciones
  L["OPT_TAB_COUNTS_TITLE"]      = "Mostrar los recuentos de correo"
  L["OPT_TAB_COUNTS_DESC"]       = "Números en Buzón y en cada botón de recogida.\n\nBuzón cuenta todos los correos del buzón, leídos incluidos; un botón cuenta lo que recogería. En cualquier caso, la pestaña Correo lleva un punto mientras quede correo por recoger."
  L["OPT_READ_MAIL_TITLE"]       = "Correo leído"
  L["OPT_READ_MAIL_DESC"]        = "Adónde va un correo leído que ya no contiene nada.\n\nBajo el buzón: tras el correo por recoger, bajo un separador que se queda al pie de una lista larga, con Borrar todo; haz clic en el separador para plegarlos. En una pestaña Hecho: un segmento propio junto a Buzón. Borrar al terminar: se borra en cuanto Postbox saca el último oro u objeto, o pulsas Volver tras leerlo; el historial guarda su texto. El correo leído que ya estaba queda bajo el separador hasta que lo borres."
  L["OPT_READ_FOLD"]             = "Bajo el buzón"
  L["OPT_READ_TAB"]              = "En una pestaña Hecho"
  L["OPT_READ_DELETE"]           = "Borrar al terminar"
  L["OPT_HISTORY_KEEP_TITLE"]    = "Guardar historial"
  L["OPT_HISTORY_KEEP_DESC"]     = "Cuántos días de correo recogido guarda el historial.\n\nMás días significa un registro mayor por personaje; nunca más de 1000 correos. Nunca: el historial se desactiva, su botón sale de la pestaña Correo y lo que guardaba se borra en todos los personajes."
  L["OPT_HISTORY_DAYS_ONE"]      = "%d día"
  L["OPT_HISTORY_DAYS_OTHER"]    = "%d días"
  L["OPT_HISTORY_NEVER"]         = "Nunca"
  L["MSG_HISTORY_OFF_CONFIRM"]   = "¿Desactivar el historial?\n\nLo que ha guardado se borra ahora en todos los personajes. No se puede deshacer."
  L["BTN_HISTORY_OFF"]           = "Desactivar"
  L["OPT_LARGER_ROWS_TITLE"]     = "Filas de correo más grandes"
  L["OPT_LARGER_ROWS_DESC"]      = "Dos líneas por correo, con un icono mayor y todas sus cifras bajo el nombre.\n\nDesactivado, cada correo ocupa una línea y la lista muestra más."
  L["OPT_ROW_LAYOUT_TITLE"]      = "Diseño de filas"
  L["OPT_ROW_LAYOUT_DESC"]       = "Cómo se alinean las cifras en las filas de correo de una línea.\n\nEl historial, la Memoria del correo y el buzón de otro personaje usan siempre una línea, y la pestaña Correo también mientras las filas de correo más grandes están desactivadas. Columnas: cada cifra queda bajo su encabezado, y un asunto largo sigue por las columnas que su correo deja vacías. Compacto: las cifras de cada fila se juntan, lejos del asunto, y el asunto se queda el espacio."
  L["OPT_ROW_LAYOUT_LARGER"]     = "Las filas de correo más grandes están activadas: las filas de la pestaña Correo ocupan dos líneas y siempre juntan las cifras de su segunda línea. El historial, la Memoria del correo y el buzón de otro personaje siguen en una línea y siguen esta opción."
  L["OPT_ROW_LAYOUT_COLUMNS"]    = "Columnas"
  L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Cada cifra queda bajo su encabezado."
  L["OPT_ROW_LAYOUT_PACKED"]     = "Compacto"
  L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Las cifras de cada fila se juntan; el asunto se queda el espacio."
  L["ARRANGE_NOTE_PACKED"]       = "Compacto: un correo sin ella no deja hueco, y el asunto ocupa su espacio."
  L["ARRANGE_LAYOUT_WHERE"]      = "Lo decide Diseño de filas, en la vista general o en las opciones, pestaña Correo."
  L["ARRANGE_LANES_ON"]          = "Cada cifra conserva su columna en cada fila. Un asunto largo sigue por las columnas que su correo deja vacías, hasta la primera cifra del correo."
  L["OPT_QUALITY_OFF"]           = "Desactivado"
  L["OPT_KEEP_FREE_TITLE"]       = "Dejar huecos libres"
  L["OPT_KEEP_FREE_DESC"]        = "La recogida se detiene dejando este número de huecos libres.\n\nEspacio para botín y profesiones. Una recogida se detiene antes del objeto que ocuparía uno de ellos, y lo dice; el oro se recoge igualmente. Un correo o un objeto en el que haces clic tú mismo se recoge igualmente. Solo cuentan las bolsas normales, no la de componentes. Ninguno: la recogida sigue hasta que tus bolsas estén llenas."
  L["OPT_KEEP_FREE_NONE"]        = "Ninguno"
  L["STATUS_KEPT_FREE_ONE"]      = "Detenido para dejar %d hueco libre"
  L["STATUS_KEPT_FREE_OTHER"]    = "Detenido para dejar %d huecos libres"
  L["MSG_COLLECT_STOPPED_KEEP_ONE"] = "%d correo sigue en el buzón: la recogida se detuvo para no ocupar %s."
  L["MSG_COLLECT_STOPPED_KEEP_OTHER"] = "%d correos siguen en el buzón: la recogida se detuvo para no ocupar %s."
  L["ROOM_KEPT_ONE"]             = "La recogida deja %d hueco libre"
  L["ROOM_KEPT_OTHER"]           = "La recogida deja %d huecos libres"
  L["BAGS_KEPT_EXTRA"]           = " (+%d reservados)"
  L["OPT_ATTACH_HOVER_TITLE"]    = "Adjuntos al pasar el ratón"
  L["OPT_ATTACH_HOVER_DESC"]     = "Lo que muestra el puntero sobre el icono de un correo con varios objetos.\n\nInformación: una lista de todo lo que contiene. En abanico: tras un momento los objetos se despliegan junto al icono, el oro primero. Clic para recoger uno, Mayús-clic para enlazarlo, Ctrl-clic para probarlo. Un correo C.R. sigue preguntando antes de recoger nada."
  L["OPT_ATTACH_HOVER_TOOLTIP"]  = "Información"
  L["OPT_ATTACH_HOVER_FAN"]      = "En abanico"
  L["FAN_TILE_HINT"]             = "Clic para recoger · Mayús-clic para enlazar"
  L["FAN_GOLD_HINT"]             = "Clic para recoger"
  L["FAN_TILE_BAGS"]             = "Tus bolsas están llenas: haz sitio para recogerlo."
  L["OPT_ICON_COUNTS_TITLE"]     = "Cantidades en los iconos"
  L["OPT_ICON_COUNTS_DESC"]      = "El tamaño de la pila en la esquina del icono de un objeto, como en las bolsas, y el borde de una segunda carta detrás del icono cuando el correo tiene más de un objeto. El nombre de un correo de la casa de subastas omite entonces la cantidad que su icono ya muestra.\n\nLa pestaña Correo, el historial y la memoria del correo la siguen."
  L["HINT_ICON_TAKE_RIGHT"]      = "Clic derecho para abrir y recoger uno a uno"
  L["HINT_ICON_TAKE_CLICK"]      = "Clic para abrir y recoger uno a uno"
  L["OPT_QUALITY_ICON_TITLE"]    = "Calidad en los iconos"
  L["OPT_QUALITY_ICON_DESC"]     = "La marca de calidad de artesanía en la esquina del icono de un objeto en las listas de correo.\n\nLa pestaña Correo, el historial y la memoria del correo la siguen."
  L["OPT_QUALITY_NAME_TITLE"]    = "Calidad junto al nombre"
  L["OPT_QUALITY_NAME_DESC"]     = "Una marca de calidad de artesanía junto al nombre de un objeto en las listas de correo, sola o con la del icono.\n\nAntes del nombre, los nombres siguen alineados. Después, como en un enlace del chat, la marca siempre se ve entera: un nombre largo se acorta para dejarle sitio. La pestaña Correo, el historial y la memoria del correo la siguen."
  L["OPT_QUALITY_NAME_BEFORE"]   = "Antes"
  L["OPT_QUALITY_NAME_AFTER"]    = "Después"
  L["HISTORY_AGE_M"]             = "%d min"
  L["HISTORY_AGE_H"]             = "%d h"
  L["HISTORY_AGE_D"]             = "%d d"
  L["HISTORY_DATE_DM"]           = "{d} {m}"
  L["HISTORY_DATE_MD"]           = "{m} {d}"
  L["HISTORY_DATE_DM_YEAR"]      = "{d} {m} {y}"
  L["HISTORY_DATE_MD_YEAR"]      = "{m} {d} {y}"
  L["OPT_SLOTS_WORDS"]           = "Número y palabra"
  L["OPT_SLOTS_NUMBER"]          = "Solo el número"
  L["COL_READ_STUCK"]            = "Un correo atascado, que no se pudo recoger, muestra aquí un triángulo de aviso."
  L["OPT_PREVIEW_CLICK_TITLE"]   = "El clic izquierdo abre el correo"
  L["OPT_PREVIEW_CLICK_DESC"]    = "El clic izquierdo abre el correo y el clic derecho lo recoge.\n\nDesactivado, se intercambian: el clic izquierdo recoge y el derecho abre sin recoger."
  L["OPT_ATTACH_MAIL_TITLE"]     = "Adjuntar desde Correo"
  L["OPT_ATTACH_MAIL_DESC"]      = "El clic derecho en un objeto de la bolsa en la pestaña Correo cambia a Enviar y lo adjunta.\n\nDesactivado, los objetos se comportan allí con normalidad. La pestaña Enviar adjunta en ambos casos."
  L["OPT_AFTER_SEND_TITLE"]      = "Tras enviar, mantener"
  L["OPT_AFTER_SEND_DESC"]       = "Lo que queda en el formulario una vez enviado el correo.\n\nNada: todo se vacía y el siguiente correo empieza en blanco. Destinatario: el nombre se queda, y el siguiente al mismo personaje no hay que volver a escribirlo. Destinatario y asunto: se quedan los dos, para una serie de correos a un mismo personaje. El mensaje, los adjuntos y el oro se vacían siempre."
  L["OPT_AFTER_SEND_NOTHING"]    = "Nada"
  L["OPT_AFTER_SEND_RECIPIENT"]  = "Destinatario"
  L["OPT_AFTER_SEND_SUBJECT"]    = "Destinatario y asunto"
  L["OPT_CATEGORY_BUTTONS_TITLE"] = "Botones de categoría"
  L["OPT_CATEGORY_BUTTONS_DESC"] = "Botones de recogida de un clic bajo la lista, uno por cada tipo de correo.\n\nComprado, vendido, cancelado, expirado, otros, de mis alters y uno por cada grupo de personajes. Desactivado, solo queda Todo el correo y la lista gana el espacio. Ocultarlos o mostrarlos al organizar es este mismo ajuste; allí también se puede mover u ocultar cada botón por separado."
  L["OPT_ROWS_HEADING"]          = "Filas de correo"
  L["OPT_GOLD_BOTH"]             = "Ganado y gastado"
  L["OPT_GOLD_EARNED"]           = "Solo ganado"
  L["OPT_GOLD_SPENT"]            = "Solo gastado"
  L["OPT_EXPIRY_ALWAYS"]         = "Siempre"
  L["OPT_EXPIRY_UNDER_ONE"]      = "Menos de %d día"
  L["OPT_EXPIRY_UNDER_OTHER"]    = "Menos de %d días"
  L["COMPARTMENT_TIP"]           = "Clic para la memoria del correo, el buzón de cada personaje · Clic derecho para opciones"
  L["OPT_ROW_GOLD"]              = "Oro"
  L["OPT_ROW_GOLD_DESC"]         = "El oro que trae un correo, en verde, y lo que costó una compra en la subasta, en rojo: elige cuál, solo para estas filas. Un precio C.R. siempre se muestra, porque Postbox nunca paga uno sin preguntar."
  L["OPT_ROW_SLOTS"]             = "Espacios"
  L["OPT_ROW_SLOTS_DESC"]        = "Cuántos espacios de adjuntos ocupa aún un correo. Oculta, el número pasa a la información de la fila."
  L["OPT_ROW_EXPIRY"]            = "Tiempo restante"
  L["OPT_ROW_EXPIRY_DESC"]       = "Cuánto le queda a un correo, en ámbar por debajo de tres días (uno para C.R.). Elige cuándo lo muestran estas filas; siempre aparece en su información."
  L["ARRANGE_TITLE"]             = "Organizar"
  L["ARRANGE_TIP"]               = "Mueve y oculta las columnas de una fila de correo y los bloques bajo la lista, y elige lo que muestran Oro, Tiempo restante, Espacios y Recogido.\n\nCada disposición guarda sus propias columnas y opciones: la pestaña Correo y la Memoria del correo comparten una, y el historial y las filas de correo más grandes tienen cada uno la suya."
  L["ARRANGE_DONE"]              = "Hecho"
  L["FRAME_TITLE_PREVIEW"]       = "Postbox · Vista previa"
  L["ARRANGE_PREVIEW_AWAY"]      = "No hay ningún buzón abierto. Esto es correo de ejemplo."
