  L["HISTORY_DATE_NUM_DM_YEAR"]  = "{dd}/{nn}/{yy}"
  L["HISTORY_DATE_NUM_MD_YEAR"]  = "{nn}/{dd}/{yy}"
  L["ARRANGE_GESTURE_OPEN"]      = "Clic para organizar"
  L["ARRANGE_RESET_CONFIRM_LARGER"] = "¿Restablecer las filas de correo más grandes?\n\nSus columnas y sus opciones vuelven a las de por defecto, igual que los bloques bajo la lista."
  L["ARRANGE_LAYOUT_LARGER"]     = "Las filas de correo más grandes siempre juntan las cifras de su segunda línea."
  L["ARRANGE_NOTE_LARGE_SIDE"]   = "En las filas de correo más grandes se coloca al principio o al final de la fila. Arrástrala al otro lado del texto para cambiar de lado."
  L["ARRANGE_NOTE_LARGE_SENDER"] = "En las filas de correo más grandes el remitente va antes del asunto o al final de la primera línea, o en la segunda línea entre las cifras. Arrástralo hacia arriba o hacia abajo para cambiar de línea."
  L["ARRANGE_NOTE_LARGE_SUBJECT"] = "En las filas de correo más grandes el asunto ocupa la primera línea, junto al remitente, o solo mientras el remitente está en la segunda línea."
