  L["ARRANGE_RESET_CONFIRM_MEMORY"] = "¿Restablecer las filas de correo de una línea?\n\nSus columnas y sus opciones vuelven a las de por defecto."
  L["WHATSNEW_TITLE"]               = "Novedades"
