  L["WHATSNEW_150_MAILBOX"]         = "En el buzón"
  L["WHATSNEW_150_MAILBOX_LINES"]   = "Los remitentes en el color de su clase; toma un solo objeto sin abrir el correo.\nDeja huecos libres al recoger; las bolsas llenas detienen la recogida limpiamente."
  L["WHATSNEW_150_HISTORY"]         = "Historial y Memoria del correo"
