  L["WHATSNEW_150_SENDING"]         = "Envío"
  L["WHATSNEW_150_SENDING_LINES"]   = "Enviar oro pregunta antes, y tú eliges qué se queda después de enviar."
  L["WHATSNEW_150_OPTIONS"]         = "Opciones, comandos e idiomas"
