  L["PERF_REC_DETAIL_DESC"]      = "Como Activado, y además lo que contenía el buzón en cada visita y los datos de objetos que el juego cargó durante ella. Algo más de trabajo en cada visita."
  L["PERF_REC_CHAT"]             = "Registro de rendimiento: %s."
