L["OPT_AFTER_SEND_TITLE"]      = "После отправки оставлять"
L["OPT_AFTER_SEND_DESC"]       = "Что остаётся в форме после отправки письма.\n\nНичего: все поля очищаются, следующее письмо начинается с чистого листа. Получателя: имя остаётся, и следующее письмо тому же персонажу не нужно адресовать заново. Получателя и тему: остаются оба, для серии писем одному персонажу. Текст, вложения и золото очищаются всегда."
