L["MSG_RESET_CONFIRM"]         = "Сбросить Postbox к исходному состоянию?\n\nСбросить настройки: все параметры в этом окне вернутся к исходным, окна Postbox — к исходным размеру и положению, а расстановка — к расстановке по умолчанию: столбцы строк писем, собственные расстановки истории и крупных строк писем, блоки под списком, а также порядок кнопок категорий и скрытые из них. Сохранятся: получатели (избранные, скрытые, заметки и добавленные вами имена), недавние получатели, группы персонажей, скрытые персонажи, память почты, история и срок её хранения, а также то, включён ли значок на миникарте.\n\nСбросить всё: всё это тоже будет стёрто, а значок на миникарте — выключен. Сохранится только список ваших персонажей. Перед этим вас спросят ещё раз."
L["BTN_RESET"]                 = "Сбросить"
L["BTN_RESET_SETTINGS"]        = "Сбросить настройки"
L["BTN_RESET_EVERYTHING"]      = "Сбросить всё"
L["MSG_RESET_ALL_CONFIRM"]     = "Сбросить всё?\n\nВсе настройки вернутся к исходным, а значок на миникарте будет выключен. Будут стёрты: получатели (избранные, скрытые, заметки и добавленные вами имена), недавние получатели, группы персонажей, скрытые персонажи, память почты и история.\n\nСохранится: список ваших персонажей. Postbox узнаёт персонажа, только когда тот входит в игру, и от этого списка зависят «От твинков», группы персонажей и список «Альты» на вкладке «Отправка».\n\nЭто действие необратимо."
L["MSG_RESET_ALL_DONE"]        = "Всё сброшено. Postbox по-прежнему знает ваших персонажей."
L["MSG_RESET_WAIT_COLLECT"]    = "Дождитесь, пока Postbox закончит забирать или удалять почту, затем выполните сброс."
L["MSG_RESET_WAIT_SEND"]       = "Дождитесь, пока Postbox закончит отправку, затем выполните сброс."
