  L["MSG_RESET_CONFIRM"]       = "将 Postbox 恢复为默认状态？\n\n重置设置：此窗口中的每个选项都会恢复为初始状态，Postbox 的窗口会恢复到初始的大小和位置，排列也会恢复默认：邮件行的列、历史和较大邮件行各自的排列、列表下方的区块，以及分类按钮的顺序和你隐藏的按钮。以下内容会保留：你的收件人（收藏、隐藏、备注和你添加的名字）、最近的收件人、你的角色分组、已隐藏的角色、邮件记忆、历史及其保留时长，以及小地图图标是否开启。\n\n全部重置：以上内容也会一并清除，小地图图标会关闭。只保留你的角色列表。执行前会再次确认。"
